import os
import subprocess
from typing import Sequence

from pants.util.osutil import get_os_name


class IdeaNotFoundException(Exception):
    """Could not find Idea executable."""


class OpenError(Exception):
    """Indicates an error opening a file in a desktop application."""


def _mac_open_with_idea(file_: str, lookup_paths: list) -> None:
    ideaPath = next((path for path in lookup_paths if os.path.isdir(path)), None)
    if ideaPath is not None:
        subprocess.call(["open", "-a", ideaPath, file_])
    else:
        raise IdeaNotFoundException(
            "Could not find Idea executable in the following locations:\n{}".format(
                "\n".join(lookup_paths)
            )
        )


def _mac_open(files: Sequence[str]) -> None:
    subprocess.call(["open"] + list(files))


def _linux_open_with_idea(file_: str, lookup_paths: list) -> None:
    cmd = "idea"
    if not _cmd_exists(cmd):
        raise OpenError(
            "The program '{}' isn't in your PATH. Please install and re-run this "
            "goal.".format(cmd)
        )
    subprocess.Popen(["nohup", cmd, file_])


def _linux_open(files: Sequence[str]) -> None:
    cmd = "xdg-open"
    if not _cmd_exists(cmd):
        raise OpenError(
            "The program '{}' isn't in your PATH. Please install and re-run this "
            "goal.".format(cmd)
        )
    for f in list(files):
        subprocess.call([cmd, f])


# From: http://stackoverflow.com/questions/377017/test-if-executable-exists-in-python
def _cmd_exists(cmd: str) -> bool:
    return (
        subprocess.call(
            ["/usr/bin/which", cmd], shell=False, stdout=subprocess.PIPE, stderr=subprocess.PIPE
        )
        == 0
    )


_OPENER_BY_OS = {"darwin": _mac_open, "linux": _linux_open}

_IDEA_BY_OS = {"darwin": _mac_open_with_idea, "linux": _linux_open_with_idea}


def idea_open(file_: str, lookup_paths: list) -> None:
    """Attempts to open the given files using the preferred desktop viewer or editor.

    :raises :class:`OpenError`: if there is a problem opening any of the files.
    """
    if file_:
        osname = get_os_name()
        opener = _IDEA_BY_OS.get(osname)
        if opener:
            opener(file_, lookup_paths)
        else:
            raise OpenError("Open currently not supported for " + osname)


def ui_open(*files: str) -> None:
    """Attempts to open the given files using the preferred desktop viewer or editor.

    :raises :class:`OpenError`: if there is a problem opening any of the files.
    """
    if files:
        osname = get_os_name()
        opener = _OPENER_BY_OS.get(osname)
        if opener:
            opener(files)
        else:
            raise OpenError("Open currently not supported for " + osname)

from lxml import etree
from nxpy.interface import Interface
from nxpy.vlan import Vlan
from nxpy.flow import Flow
from util import tag_pattern


class Device(object):

    # Singleton
    _instance = None

    def __new__(cls, *args, **kwargs):
        if not cls._instance:
            cls._instance = super(
                Device, cls).__new__(cls, *args, **kwargs)
        return cls._instance

    def __init__(self):
        self.name = ''
        self.domain_name = ''
        self.interfaces = []
        self.vlans = []
        self.routing_options = []

    def export(self, netconf_config=False):
        config = etree.Element("configuration")
        device = etree.Element('system')
        if self.name:
            etree.SubElement(device, "host-name").text = self.name
        if self.domain_name:
            etree.SubElement(device, "domain-name").text = self.domain_name
        if len(device.getchildren()):
            config.append(device)
        interfaces = etree.Element('interfaces')
        if len(self.interfaces):
            for interface in self.interfaces:
                if (interface):
                    interfaces.append(interface.export())
            config.append(interfaces)
        vlans = etree.Element('vlans')
        if len(self.vlans):
            for vlan in self.vlans:
                if (vlan):
                    vlans.append(vlan.export())
            config.append(vlans)
        routing_options = etree.Element('routing-options')
        if len(self.routing_options):
            for ro in self.routing_options:
                if (ro):
                    routing_options.append(ro.export())
            config.append(routing_options)
        if netconf_config:
            conf = etree.Element("config")
            conf.append(config)
            config = conf
        if len(config.getchildren()):
            return config
        else:
            return False

    def build(self, node):
        for child in node:
            nodeName_ = tag_pattern.match(child.tag).groups()[-1]
            self.buildChildren(child, nodeName_)

    def buildChildren(self, child_, nodeName_, from_subclass=False):
        if nodeName_ == 'interfaces':
            for node in child_:
                obj_ = Interface()
                obj_.build(node)
                self.interfaces.append(obj_)
        if nodeName_ == 'vlans':
            for node in child_:
                obj_ = Vlan()
                obj_.build(node)
                self.vlans.append(obj_)
        if nodeName_ == 'routing-options':
            for node in child_:
                childName_ = tag_pattern.match(node.tag).groups()[-1]
                # *************** FLOW ****************
                if childName_ == 'flow':
                    obj_ = Flow()
                    obj_.build(node)
                    self.routing_options.append(obj_)
